/**
 * Глобальные объекты браузерной сборки LibreOffice.
 *
 * Сборка — это Emscripten-модуль, и точка соприкосновения с ней одна:
 * глобальный `Module`. Он объявляется здесь, а не импортируется, потому что
 * другого способа у сборки нет: `soffice.js` — классический скрипт, который
 * читает и дописывает этот объект.
 *
 * `FS` объявлен отдельно: на главном потоке сборка кладёт файловую систему
 * в `window.FS`, а в воркере — в `Module.FS`. Файловая система при этом одна,
 * и это единственный канал, по которому содержимое документа попадает
 * в офис и возвращается обратно.
 */

import type { EmscriptenFs, LowaModule } from './types.js';

declare global {
  // eslint-disable-next-line no-var -- объявление глобального объекта сборки
  var Module: LowaModule | undefined;

  /**
   * Виртуальная файловая система сборки на главном потоке.
   *
   * Объявлена глобальной, а не свойством `Window`: в воркере она же лежит
   * в `Module.FS`, и разница только в способе доступа. Тип общий, потому что
   * файловая система одна.
   */
  // eslint-disable-next-line no-var -- объявление глобального объекта сборки
  var FS: EmscriptenFs | undefined;
}

export {};
